// Etiquetas para imprimir: diseño 10x15 cm + QR, 2 por hoja A4, en PDF
window.Labels = (() => {
  const { esc, qrPNG, fileName } = UI;
  const $ = (s) => document.querySelector(s);
  const W = 10, H = 15; // cm de la etiqueta
  const DPI = 300, PX = DPI / 2.54; // pixeles por cm
  const PAGE = { w: 21, h: 29.7 }; // A4
  // Acomodo en la hoja A4. rot = etiqueta acostada (girada 90°)
  const LAYOUTS = {
    3: [{ x: 0.5, y: 2.05 }, { x: 10.5, y: 2.05 }, { x: 3, y: 17.65, rot: true }],
    2: [{ x: 0.5, y: 1.2 }, { x: 10.5, y: 1.2 }],
  };

  // Diseños incluidos. Cada uno trae dónde va el QR y el texto
  const TPL = {
    blanco: { label: 'Blanco', qrX: 3.0, qrY: 7.75, qrSize: 4.0, frame: false, text: 'none', textY: 13.1, textSize: 0.45, textColor: '#111827' },
    negro: { label: 'Negro', qrX: 3.0, qrY: 7.75, qrSize: 4.0, frame: false, text: 'none', textY: 13.1, textSize: 0.45, textColor: '#ffffff' },
    imagen: { label: 'Mi imagen', qrX: 2.5, qrY: 5.2, qrSize: 5, frame: true, text: 'client', textY: 11.2, textSize: 0.6, textColor: '#1f2937' },
  };
  const DEF = { tpl: 'blanco', layout: 3, marks: true, folio: true, ...posOf('blanco') };
  function posOf(t) { const { label, ...p } = TPL[t]; return p; }
  let cfg = { ...DEF }, design = null, designImg = null, rows = [];
  try {
    const saved = JSON.parse(localStorage.getItem('lbl-cfg') || '{}');
    if (saved.v === 3) Object.assign(cfg, saved);
  } catch {}
  cfg.v = 3;
  // Ícono incluido por defecto
  const DEF_LOGO = 'data:image/png;base64,';
  let defLogoImg = null;
  let logo = null, logoImg = null;
  try { logo = localStorage.getItem('lbl-logo'); } catch {}
  try { design = localStorage.getItem('lbl-design'); } catch {}
  const saveCfg = () => { try { localStorage.setItem('lbl-cfg', JSON.stringify(cfg)); } catch {} };

  function loadImg(src) {
    return new Promise((res, rej) => { const i = new Image(); i.onload = () => res(i); i.onerror = rej; i.src = src; });
  }

  // ---------- Diseños incluidos (todo en cm) ----------
  const FONT = 'Poppins, system-ui, sans-serif';
  let fontsReady = null;
  const ensureFonts = () => (fontsReady ||= Promise.all(['800 40px Poppins', '600 40px Poppins', '500 40px Poppins']
    .map((f) => document.fonts.load(f).catch(() => {}))));

  function star(g, cx, cy, r) {
    g.beginPath();
    for (let i = 0; i < 10; i++) {
      const a = -Math.PI / 2 + (i * Math.PI) / 5, rr = i % 2 ? r * 0.45 : r;
      g.lineTo(cx + rr * Math.cos(a), cy + rr * Math.sin(a));
    }
    g.closePath(); g.fill();
  }
  function txt(g, cm, t, x, y, size, weight, color, spacing = 0) {
    g.fillStyle = color; g.textAlign = 'center'; g.textBaseline = 'middle';
    g.font = `${weight} ${size * cm}px ${FONT}`;
    if ('letterSpacing' in g) g.letterSpacing = spacing * cm + 'px';
    g.fillText(t, x * cm, y * cm);
    if ('letterSpacing' in g) g.letterSpacing = '0px';
  }
  function drawTemplate(g, cm, dark) {
    const X = (v) => v * cm;
    const ink = dark ? '#ffffff' : '#0f172a', soft = dark ? '#a1a1aa' : '#64748b';
    const acc = dark ? '#60a5fa' : '#2563eb', acc2 = dark ? '#a78bfa' : '#7c3aed', gold = '#f5b301';
    // fondo con degradado suave
    if (dark) {
      const bg = g.createLinearGradient(0, 0, 0, X(H)); bg.addColorStop(0, '#151a24'); bg.addColorStop(1, '#060607');
      g.fillStyle = bg; g.fillRect(0, 0, X(W), X(H));
    } else { g.fillStyle = '#ffffff'; g.fillRect(0, 0, X(W), X(H)); }
    const glow = g.createRadialGradient(X(W / 2), X(3.6), 0, X(W / 2), X(3.6), X(5.5));
    glow.addColorStop(0, dark ? 'rgba(96,165,250,.16)' : 'rgba(37,99,235,.08)'); glow.addColorStop(1, 'rgba(37,99,235,0)');
    g.fillStyle = glow; g.fillRect(0, 0, X(W), X(H));
    // marco
    g.strokeStyle = dark ? 'rgba(255,255,255,.12)' : 'rgba(15,23,42,.10)'; g.lineWidth = X(0.035);
    g.beginPath(); g.roundRect(X(0.35), X(0.35), X(W - 0.7), X(H - 0.7), X(0.5)); g.stroke();

    // botón NFC
    {
      const label = 'ACERCA TU CELULAR · NFC', fs = 0.33;
      g.font = `700 ${X(fs)}px ${FONT}`;
      if ('letterSpacing' in g) g.letterSpacing = X(0.02) + 'px';
      const tw = g.measureText(label).width / cm, iw = 0.95, gap = 0.45;
      const pw = iw + gap + tw + 0.9, ph = 1.1, px = W / 2 - pw / 2, py = 0.75;
      const pg = g.createLinearGradient(X(px), 0, X(px + pw), 0); pg.addColorStop(0, acc); pg.addColorStop(1, acc2);
      g.save(); g.shadowColor = dark ? 'rgba(96,165,250,.45)' : 'rgba(37,99,235,.30)'; g.shadowBlur = X(0.35); g.shadowOffsetY = X(0.06);
      g.fillStyle = pg; g.beginPath(); g.roundRect(X(px), X(py), X(pw), X(ph), X(ph / 2)); g.fill(); g.restore();
      const gx = px + 0.45, cy = py + ph / 2;
      tapIcon(g, cm, gx + iw / 2, cy, '#ffffff');
      g.fillStyle = '#ffffff'; g.textAlign = 'left'; g.textBaseline = 'middle';
      g.font = `700 ${X(fs)}px ${FONT}`;
      g.fillText(label, X(gx + iw + gap), X(cy));
      if ('letterSpacing' in g) g.letterSpacing = '0px';
    }
    // separador que se desvanece
    const sep = g.createLinearGradient(X(1), 0, X(W - 1), 0);
    const sc = dark ? 'rgba(255,255,255,' : 'rgba(15,23,42,';
    sep.addColorStop(0, sc + '0)'); sep.addColorStop(0.5, sc + '.18)'); sep.addColorStop(1, sc + '0)');
    g.fillStyle = sep; g.fillRect(X(1), X(2.2), X(W - 2), X(0.03));

    // ícono grande
    const lg = logoImg || defLogoImg;
    if (lg) {
      const maxW = 5, maxH = 1.65, r = lg.width / lg.height;
      let lw = maxW, lh = lw / r; if (lh > maxH) { lh = maxH; lw = lh * r; }
      g.save(); g.shadowColor = 'rgba(0,0,0,' + (dark ? '.5' : '.12') + ')'; g.shadowBlur = X(0.25); g.shadowOffsetY = X(0.05);
      g.drawImage(lg, X(W / 2 - lw / 2), X(3.05 - lh / 2), X(lw), X(lh)); g.restore();
    } else txt(g, cm, 'Google', W / 2, 3.05, 0.9, 700, ink);
    // estrellas con brillo
    g.save(); g.fillStyle = gold; g.shadowColor = 'rgba(245,179,1,' + (dark ? '.55' : '.35') + ')'; g.shadowBlur = X(0.18);
    for (let i = 0; i < 5; i++) star(g, X(W / 2 + (i - 2) * 0.82), X(4.28), X(0.32));
    g.restore();
    // título
    txt(g, cm, 'Tu opinión', W / 2, 5.12, 0.86, 800, ink);
    g.font = `800 ${X(0.86)}px ${FONT}`;
    const tg = g.createLinearGradient(X(2), 0, X(8), 0); tg.addColorStop(0, acc); tg.addColorStop(1, acc2);
    txt(g, cm, 'nos importa', W / 2, 5.98, 0.86, 800, tg);
    txt(g, cm, 'Déjanos tu reseña en Google', W / 2, 6.68, 0.36, 500, soft);

    // QR: tarjeta con sombra + esquinas de escaneo
    g.save(); g.shadowColor = dark ? 'rgba(96,165,250,.35)' : 'rgba(15,23,42,.18)'; g.shadowBlur = X(0.4); g.shadowOffsetY = X(0.08);
    g.fillStyle = '#ffffff'; g.beginPath(); g.roundRect(X(2.7), X(7.45), X(4.6), X(4.6), X(0.4)); g.fill(); g.restore();
    g.strokeStyle = tg; g.lineWidth = X(0.11); g.lineCap = 'round';
    const bx0 = 2.45, by0 = 7.2, bx1 = 7.55, by1 = 12.3, L = 0.75;
    for (const [x, y, dx, dy] of [[bx0, by0, 1, 1], [bx1, by0, -1, 1], [bx0, by1, 1, -1], [bx1, by1, -1, -1]]) {
      g.beginPath(); g.moveTo(X(x), X(y + dy * L)); g.lineTo(X(x), X(y + dy * 0.2));
      g.quadraticCurveTo(X(x), X(y), X(x + dx * 0.2), X(y)); g.lineTo(X(x + dx * L), X(y)); g.stroke();
    }
    g.lineCap = 'butt';
    // botón "Escanea el QR"
    {
      const label = 'ESCANEA EL QR', fs = 0.32;
      g.font = `700 ${X(fs)}px ${FONT}`;
      if ('letterSpacing' in g) g.letterSpacing = X(0.03) + 'px';
      const tw = g.measureText(label).width / cm, pw = tw + 1.0, ph = 0.72, px = W / 2 - pw / 2, py = 12.6;
      g.strokeStyle = acc; g.lineWidth = X(0.05);
      g.fillStyle = dark ? 'rgba(96,165,250,.12)' : 'rgba(37,99,235,.07)';
      g.beginPath(); g.roundRect(X(px), X(py), X(pw), X(ph), X(ph / 2)); g.fill(); g.stroke();
      g.fillStyle = acc; g.textAlign = 'center'; g.textBaseline = 'middle';
      g.fillText(label, X(W / 2), X(py + ph / 2 + 0.01));
      if ('letterSpacing' in g) g.letterSpacing = '0px';
    }
    // pie
    txt(g, cm, '¡Gracias por tu visita!', W / 2, 13.85, 0.32, 500, soft);
    g.fillStyle = tg; g.beginPath(); g.roundRect(X(4.1), X(14.2), X(1.8), X(0.08), X(0.04)); g.fill();
  }
  function txtL(g, cm, t, x, y, size, weight, color) {
    g.fillStyle = color; g.textAlign = 'left'; g.textBaseline = 'middle';
    g.font = `${weight} ${size * cm}px ${FONT}`; g.fillText(t, x * cm, y * cm);
  }
  // Ícono de "acercar el celular": teléfono inclinado con ondas saliendo
  function tapIcon(g, cm, cx, cy, color) {
    g.save();
    g.translate((cx - 0.12) * cm, cy * cm); g.rotate(-0.26);
    g.strokeStyle = color; g.lineWidth = 0.07 * cm; g.lineJoin = 'round';
    g.beginPath(); g.roundRect(-0.24 * cm, -0.4 * cm, 0.48 * cm, 0.8 * cm, 0.09 * cm); g.stroke();
    g.fillStyle = color; g.beginPath(); g.arc(0, 0.29 * cm, 0.035 * cm, 0, Math.PI * 2); g.fill();
    g.restore();
    g.strokeStyle = color; g.lineCap = 'round'; g.lineWidth = 0.065 * cm;
    for (const r of [0.2, 0.36, 0.52]) {
      g.beginPath(); g.arc((cx + 0.1) * cm, (cy - 0.05) * cm, r * cm, -Math.PI * 0.3, Math.PI * 0.3); g.stroke();
    }
    g.lineCap = 'butt';
  }
  // Ícono genérico de "acercar el celular": teléfono + ondas (s = escala)
  function nfcIcon(g, cm, cx, cy, ink, acc, s = 1) {
    const pw = 1.35 * s, ph = 2.35 * s, px = cx - pw / 2 + 0.45 * s, py = cy - ph / 2;
    g.strokeStyle = ink; g.lineWidth = 0.09 * cm * Math.max(s, 0.6); g.lineJoin = 'round';
    g.beginPath(); g.roundRect(px * cm, py * cm, pw * cm, ph * cm, 0.22 * s * cm); g.stroke();
    g.beginPath(); g.moveTo((px + pw / 2 - 0.2 * s) * cm, (py + 0.22 * s) * cm); g.lineTo((px + pw / 2 + 0.2 * s) * cm, (py + 0.22 * s) * cm); g.stroke();
    g.fillStyle = ink; g.beginPath(); g.arc((px + pw / 2) * cm, (py + ph - 0.25 * s) * cm, 0.08 * s * cm, 0, Math.PI * 2); g.fill();
    g.strokeStyle = acc; g.lineCap = 'round'; g.lineWidth = 0.1 * cm * Math.max(s, 0.6);
    const ox = px - 0.3 * s;
    for (const r of [0.35, 0.7, 1.05]) {
      g.beginPath(); g.arc(ox * cm, cy * cm, r * s * cm, Math.PI * 0.72, Math.PI * 1.28); g.stroke();
    }
    g.lineCap = 'butt';
  }

  // Dibuja una etiqueta completa en un canvas a 300 dpi
  async function render(qr, scale = 1) {
    const w = Math.round(W * PX * scale), h = Math.round(H * PX * scale), cm = PX * scale;
    const c = document.createElement('canvas'); c.width = w; c.height = h;
    const g = c.getContext('2d');
    await ensureFonts();
    if (cfg.tpl === 'imagen' && designImg) {
      g.fillStyle = '#fff'; g.fillRect(0, 0, w, h);
      g.drawImage(designImg, 0, 0, w, h);
    } else drawTemplate(g, cm, cfg.tpl === 'negro');
    const s = cfg.qrSize * cm, x = cfg.qrX * cm, y = cfg.qrY * cm;
    if (cfg.frame) {
      const p = 0.25 * cm;
      g.fillStyle = '#fff';
      g.beginPath(); g.roundRect(x - p, y - p, s + 2 * p, s + 2 * p, 0.3 * cm); g.fill();
    }
    const q = await loadImg(qrPNG(qr.url, null, Math.max(600, Math.round(s))));
    // el PNG ya trae margen blanco de 4 módulos; se recorta para que mida exactamente lo indicado
    const n = q.width, crop = n * (4 / (qrcodeModules(qr.url) + 8));
    g.imageSmoothingEnabled = false;
    g.drawImage(q, crop, crop, n - 2 * crop, n - 2 * crop, x, y, s, s);
    const label = cfg.text === 'client' ? qr.client || qr.name : cfg.text === 'name' ? qr.name : '';
    if (label) {
      g.fillStyle = cfg.textColor; g.textAlign = 'center'; g.textBaseline = 'middle';
      let fs = cfg.textSize * cm;
      g.font = `700 ${fs}px ${FONT}`;
      while (g.measureText(label).width > w * 0.84 && fs > 8) { fs -= 2; g.font = `700 ${fs}px ${FONT}`; }
      g.fillText(label, w / 2, cfg.textY * cm);
    }
    // número de folio chiquito en la esquina, para no confundirse al cortar
    if (cfg.folio !== false && qr.name) {
      const dark = cfg.tpl === 'negro';
      g.font = `600 ${0.24 * cm}px ${FONT}`; g.textAlign = 'right'; g.textBaseline = 'alphabetic';
      g.fillStyle = cfg.tpl === 'imagen' ? 'rgba(0,0,0,.55)' : dark ? 'rgba(255,255,255,.45)' : 'rgba(15,23,42,.4)';
      g.fillText(qr.name, w - 0.7 * cm, h - 0.62 * cm);
    }
    return c;
  }
  function rotate(c) {
    const r = document.createElement('canvas'); r.width = c.height; r.height = c.width;
    const g = r.getContext('2d'); g.translate(r.width, 0); g.rotate(Math.PI / 2); g.drawImage(c, 0, 0);
    return r;
  }
  function qrcodeModules(text) { const q = qrcode(0, 'M'); q.addData(text); q.make(); return q.getModuleCount(); }

  // ---------- Diálogo ----------
  function open(preselectId) {
    const q = $('#lQ').value = '';
    // Por cada QR va un par (2 iguales)
    const fc = $('#fc').value;
    const pre = preselectId == null ? null : [].concat(preselectId).map(String);
    rows = QRS.filter((x) => x.active).map((x) => ({ ...x, n: pre ? (pre.includes(String(x.id)) ? 2 : 0) : (!fc || x.client === fc ? 2 : 0) }));
    syncForm(); renderRows(); preview();
    $('#dlgLabels').showModal();
  }
  function syncForm() {
    const f = $('#fLabels');
    for (const k of ['qrX', 'qrY', 'qrSize', 'textY', 'textSize']) f[k].value = cfg[k];
    f.frame.checked = cfg.frame; f.marks.checked = cfg.marks; f.folio.checked = cfg.folio !== false; f.text.value = cfg.text; f.textColor.value = cfg.textColor;
    f.layout.value = cfg.layout;
    document.querySelectorAll('#lTpl [data-tpl]').forEach((b) => b.classList.toggle('on', b.dataset.tpl === cfg.tpl));
    $('#lUpload').hidden = cfg.tpl !== 'imagen';
    $('#lLogoBox').hidden = cfg.tpl === 'imagen';
    $('#lLogoName').textContent = logo ? 'Ícono propio cargado' : 'Usando el ícono incluido';
    $('#lLogoClear').hidden = !logo;
    $('#lDesignName').textContent = design ? 'Imagen cargada' : 'Todavía no subes tu imagen';
    $('#lDesignClear').hidden = !design;
  }
  function renderRows() {
    const q = $('#lQ').value.trim().toLowerCase();
    const list = rows.filter((r) => !q || [r.name, r.client].join(' ').toLowerCase().includes(q));
    $('#lRows').innerHTML = list.length ? list.map((r) => `
      <div class="lrow"><div><b>${esc(r.name)}</b><div class="muted small">${esc(r.client || '')}</div></div>
      <input type="number" min="0" max="200" value="${r.n}" data-id="${r.id}" aria-label="Cantidad"></div>`).join('')
      : '<div class="muted small" style="padding:10px">No hay QR activos.</div>';
    totals();
  }
  function totals() {
    const n = rows.reduce((a, r) => a + r.n, 0), per = +cfg.layout, hojas = Math.ceil(n / per);
    $('#lTotal').textContent = n ? `${n} etiqueta${n === 1 ? '' : 's'} · ${hojas} hoja${hojas === 1 ? '' : 's'} A4` : 'Pon cuántas etiquetas quieres de cada QR';
    $('#lMake').disabled = !n;
  }
  let pvTimer;
  function preview() {
    clearTimeout(pvTimer);
    pvTimer = setTimeout(async () => {
      const first = rows.find((r) => r.n) || rows[0] || { name: 'Tu negocio', client: 'Tu negocio', slug: 'demo' };
      const c = await render({ ...first, url: ORIGIN + '/r/' + first.slug }, 0.35);
      const pv = $('#lPreview'); pv.innerHTML = ''; c.style.width = '100%'; c.style.height = 'auto'; pv.appendChild(c);
    }, 120);
  }

  async function makePDF() {
    const items = orderItems(rows.filter((r) => r.n > 0), (LAYOUTS[cfg.layout] || LAYOUTS[3]).length);
    if (!items.length) return;
    const btn = $('#lMake'); btn.disabled = true;
    try {
      const { jsPDF } = window.jspdf;
      const pdf = new jsPDF({ unit: 'cm', format: 'a4', orientation: 'portrait' });
      const cache = {}, slots = LAYOUTS[cfg.layout] || LAYOUTS[3];
      for (let i = 0; i < items.length; i++) {
        btn.textContent = `Armando ${i + 1} de ${items.length}…`;
        const it = items[i];
        if (i && i % slots.length === 0) pdf.addPage();
        const slot = slots[i % slots.length];
        const k = it.id + (slot.rot ? 'r' : '');
        if (!cache[k]) {
          const c = await render({ ...it, url: ORIGIN + '/r/' + it.slug });
          cache[k] = (slot.rot ? rotate(c) : c).toDataURL('image/jpeg', 0.93);
        }
        const w = slot.rot ? H : W, h = slot.rot ? W : H;
        pdf.addImage(cache[k], 'JPEG', slot.x, slot.y, w, h, 'l' + k, 'FAST');
        if (cfg.marks) cropMarks(pdf, slot.x, slot.y, w, h);
      }
      const names = [...new Set(items.map((x) => x.client || x.name))];
      const fname = 'etiquetas-' + (names.length === 1 ? fileName(names[0]) : 'varias') + '.pdf';
      window.Labels.deliver(pdf, fname);
    } catch (e) { toast('No se pudo hacer el PDF: ' + e.message); }
    finally { btn.disabled = false; btn.textContent = 'Descargar PDF'; totals(); }
  }
  // Acomodo: si todos los QR llevan la misma cantidad (ej. su par), se agrupan de 3 en 3
  // y cada hoja lleva una cara de cada uno: hoja 1 = A B C, hoja 2 = A B C (mismo lugar).
  // Los que sobran (1 o 2 QR) se acomodan seguidos para no gastar hojas de más.
  function orderItems(list, per) {
    if (!list.length) return [];
    const n = list[0].n;
    if (!list.every((r) => r.n === n)) return list.flatMap((r) => Array(r.n).fill(r));
    const full = Math.floor(list.length / per) * per, out = [];
    for (let i = 0; i < full; i += per) {
      const grp = list.slice(i, i + per);
      for (let k = 0; k < n; k++) out.push(...grp);
    }
    list.slice(full).forEach((r) => { for (let k = 0; k < n; k++) out.push(r); });
    return out;
  }

  // Marcas de corte en las esquinas, por fuera de la etiqueta
  function cropMarks(pdf, x, y, w = W, h = H) {
    pdf.setDrawColor(120); pdf.setLineWidth(0.01);
    const L = 0.35, o = 0.08;
    for (const [cx, cy, dx, dy] of [[x, y, -1, -1], [x + w, y, 1, -1], [x, y + h, -1, 1], [x + w, y + h, 1, 1]]) {
      pdf.line(cx + dx * o, cy, cx + dx * (o + L), cy);
      pdf.line(cx, cy + dy * o, cx, cy + dy * (o + L));
    }
  }

  // ---------- Eventos ----------
  document.addEventListener('DOMContentLoaded', () => {});
  function wire() {
    const f = $('#fLabels');
    f.addEventListener('input', (e) => {
      const t = e.target;
      if (t.dataset.id) { const r = rows.find((x) => x.id == t.dataset.id); r.n = Math.max(0, Math.min(200, +t.value || 0)); totals(); preview(); return; }
      if (t.id === 'lQ') return renderRows();
      if (t.name in cfg) {
        cfg[t.name] = t.type === 'checkbox' ? t.checked : t.type === 'number' || t.name === 'layout' ? +t.value : t.value;
        saveCfg(); preview(); totals();
      }
    });
    f.addEventListener('change', (e) => { if (e.target.name === 'text' || e.target.type === 'checkbox') { cfg[e.target.name] = e.target.type === 'checkbox' ? e.target.checked : e.target.value; saveCfg(); preview(); } });
    $('#lDesign').onchange = async (e) => {
      const file = e.target.files[0]; if (!file) return;
      if (!/^image\/(png|jpe?g|webp)$/.test(file.type)) return toast('Sube tu diseño como imagen PNG o JPG');
      const url = await new Promise((res) => { const r = new FileReader(); r.onload = () => res(r.result); r.readAsDataURL(file); });
      const img = await loadImg(url);
      const ratio = img.width / img.height;
      if (Math.abs(ratio - W / H) > 0.03) toast('Ojo: tu imagen no es de 10×15 cm (vertical). Se va a estirar para llenar la etiqueta.');
      design = url; designImg = img; cfg.tpl = 'imagen'; saveCfg();
      try { localStorage.setItem('lbl-design', url); } catch { toast('El diseño es muy pesado para guardarlo, vas a tener que subirlo cada vez'); }
      syncForm(); preview();
    };
    $('#lLogo').onchange = async (e) => {
      const file = e.target.files[0]; if (!file) return;
      if (!/^image\/(png|jpe?g|webp|svg\+xml)$/.test(file.type)) return toast('Sube el logo como PNG (de preferencia con fondo transparente)');
      const url = await new Promise((res) => { const r = new FileReader(); r.onload = () => res(r.result); r.readAsDataURL(file); });
      logo = url; logoImg = await loadImg(url);
      try { localStorage.setItem('lbl-logo', url); } catch { toast('El logo es muy pesado para guardarlo'); }
      syncForm(); preview();
    };
    $('#lLogoClear').onclick = () => { logo = logoImg = null; try { localStorage.removeItem('lbl-logo'); } catch {} syncForm(); preview(); };
    $('#lDesignClear').onclick = () => { design = designImg = null; try { localStorage.removeItem('lbl-design'); } catch {} syncForm(); preview(); };
    $('#lReset').onclick = () => { Object.assign(cfg, posOf(cfg.tpl)); saveCfg(); syncForm(); preview(); };
    $('#lTpl').onclick = (e) => {
      const b = e.target.closest('[data-tpl]'); if (!b) return;
      cfg.tpl = b.dataset.tpl; Object.assign(cfg, posOf(cfg.tpl));
      saveCfg(); syncForm(); preview();
    };
    $('#lMake').onclick = makePDF;
    $('#lAll').onclick = () => { rows.forEach((r) => (r.n = r.n || 2)); renderRows(); preview(); };
    $('#lNone').onclick = () => { rows.forEach((r) => (r.n = 0)); renderRows(); preview(); };
  }

  (async () => {
    if (design) { try { designImg = await loadImg(design); } catch { design = null; } }
    if (logo) { try { logoImg = await loadImg(logo); } catch { logo = null; } }
    try { defLogoImg = await loadImg(DEF_LOGO); } catch {}
    wire();
  })();

  return {
    open,
    deliver(pdf, name) { pdf.save(name); toast('PDF listo'); },
  };
})();
